/**
 * The deployable-entity shape every builder's `def(refName)` returns — the
 * seam between authoring (`defineX` builders) and everything that consumes
 * authored entities (discovery, `appToTf`, catalog regeneration). Extracted
 * from the deleted REST deploy planner: the SHAPE outlived the engine.
 */
import type { CatalogRefKind } from "../catalog/types.js";
export interface EntityDeployOptions {
    /** Deploy-time enabled control. When false, the entity is ignored (as if omitted). */
    readonly enabled?: boolean;
}
/** A deployable entity: its source identity + handle-form payload. */
export interface DeployableEntity extends EntityDeployOptions {
    readonly kind: CatalogRefKind;
    /** The owning parent's handle (app/element/table) — resolves which per-aspect state it lives in. */
    readonly parent: string;
    /** EDK source/catalog/state identity, usually derived from the authoring file refName. */
    readonly refName: string;
    /** Handle-form payload (cross-entity refs are `CatalogRef` tokens, volatile ids stripped). */
    readonly payload: unknown;
}
/**
 * Owning-app refName context for an automation's record-bearing trigger/task
 * refs — `automation.def()` attaches it as a structural extension on
 * the object it returns (deliberately not a declared property: every other
 * kind would carry a slot that never applies to it). The terraform-path
 * automation emitter (M4) is its consumer.
 */
export interface RecordFieldContext {
    /** The trigger's owning app refName, when its `record` output is app-field-typed. */
    readonly triggerAppRefName?: string;
    /** Each record-bearing task's refKey → its owning app refName. */
    readonly taskAppRefNameByRefKey?: Readonly<Record<string, string>>;
}
/** Read the `recordFieldContext` extension off an entity, if its producer attached one. */
export declare function recordFieldContextOf(entity: DeployableEntity): RecordFieldContext | undefined;
/**
 * Structural breakage in an entity's to-tf/from-tf (a missing label, a
 * non-canonical bag key) — loud, never a degradation. Degradations go
 * through the context's `diagnostics` instead.
 */
export declare class EntityTfError extends Error {
    constructor(message: string);
}
